bash_results.command:
F=$(mktemp -d); U=teamwork/skills/kick-off/scripts/use-board.py; echo b > $F/b; torn=0; for r in 1 2 3; do export TEAMWORK_BOARD=files TEAMWORK_BOARD_DIR=$F/$r HOME=$F CLAUDE_CONFIG_DIR=$F; python3 $U file T $F/b >/dev/null; { seq 40 | sed 's/^/label 1 L/'; seq 40 | sed "s|.*|comment 1 $F/b|"; } > $F/ops; { xargs -P 80 -L1 python3 $U < $F/ops; touch $F/done$r; } >/dev/null 2>&1 & n=$(python3 -c "$(printf 'import json, pathlib, sys
b, done, bad = pathlib.Path(sys.argv[1]), pathlib.Path(sys.argv[2]), 0
while not done.exists():
    try:
        json.loads((b / "1/issue.json").read_text()); bad += not all(path.read_text() for path in [b / "1/body.md", *(b / "1/comments").glob("*.md")])
    except (ValueError, OSError):
        bad += 1
print(bad)')" $F/$r $F/done$r); wait; [ "$n" = 0 ] || torn=$((torn+1)); done; echo $torn
cd teamwork/skills/kick-off/fixtures; for s in "replay-board-scenario.py --board files" replay-nest-target.py replay-files-pane.py replay-data-folder.py replay-board-setting.py; do python3 $s 2>&1 | tail -2; done

